  ('inspiration', 'More Inspiration'),
  ('ai-code', 'AI Code'),
  ('components', 'Components'),
  ('web-utility', 'Web Utility'),
  ('desktop-utility', 'Desktop Utility'),
  ('video-and-capture', 'Video & Capture'),
  ('whiteboard', 'Whiteboard'),
  ('organization', 'Organization'),
  ('fonts', 'Fonts'),
  ('visual', 'Visual'),
  ('interface', 'Interface'),
  ('motion', 'Motion'),
  ('audio', 'Audio'),
  ('volumetric', 'Volumetric'),
  ('3d', '3D'),
  ('gltf', 'glTF'),
  ('digital-fashion', 'Digital Fashion'),
  ('research', 'Research'),
  ('browser', 'Browser'),
  ('emoji', 'Emoji'),
  ('utility', 'Utility'),
  ('resources', 'Resources'),
  ('learning', 'Learning'),
  ('ai', 'AI Tools'),
  ('tool', 'Tools'),
  ('productivity', 'Productivity'),
  ('collection', 'Collections'),
  ('reading', 'Reading')
on conflict do nothing;

-- Same link = same site, ignoring protocol, www. and a trailing slash.
create or replace function pg_temp.norm(l text) returns text language sql as
  $$ select lower(regexp_replace(regexp_replace(l, '^https?://(www\.)?', ''), '/+$', '')) $$;

insert into bookmarks (slug, title, link, favicon, category_slug, created_at)
